<?php
require __DIR__.'/auth.php';requireAdmin();require dirname(__DIR__).'/includes/bootstrap.php';require dirname(__DIR__).'/includes/listings.php';require_once dirname(__DIR__).'/Config/blog-store.php';
$db=adminDb();$errors=[];$edit=max(0,(int)($_GET['edit']??0));$editing=isset($_GET['new'])||$edit>0;
$defaults=blogDefaults();$defaults['author']=currentUser()['name']?:'Royalmark Estate';$defaults['published_at']=date('Y-m-d\TH:i');$data=$defaults;
if($edit){$q=$db->prepare('SELECT id,slug,payload FROM blog_posts WHERE id=?');$q->execute([$edit]);$row=$q->fetch();if(!$row){http_response_code(404);$errors[]='Post not found.';$editing=false;}else $data=blogRecord($row);}
function blogEditorRedirect(string $notice): never {$_SESSION['blog_notice']=$notice;header('Location: ./blog');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 adminCsrf();$action=is_string($_POST['action']??null)?$_POST['action']:'';$id=max(0,(int)($_POST['id']??0));$old=null;
 if($id){$q=$db->prepare('SELECT id,slug,payload FROM blog_posts WHERE id=?');$q->execute([$id]);$row=$q->fetch();if($row)$old=blogRecord($row);else $errors[]='Post no longer exists.';}
 if(in_array($action,['delete','publish','unpublish'],true)){
  if(!$id)$errors[]='Choose a post first.';
  if(!$errors){try{
   $db->beginTransaction();
   if($action==='delete'){$db->prepare('DELETE FROM blog_comments WHERE post_id=?')->execute([$id]);$db->prepare('DELETE FROM blog_posts WHERE id=?')->execute([$id]);}
   else{$q=$db->prepare('SELECT payload FROM blog_posts WHERE id=? FOR UPDATE');$q->execute([$id]);$payload=$q->fetchColumn();if($payload===false)throw new RuntimeException('Post no longer exists.');$next=json_decode($payload,true,512,JSON_THROW_ON_ERROR);$next['status']=$action==='publish'?'published':'draft';if($action==='publish'&&empty($next['published_at']))$next['published_at']=date('Y-m-d\TH:i');$db->prepare('UPDATE blog_posts SET payload=? WHERE id=?')->execute([json_encode($next,JSON_THROW_ON_ERROR),$id]);}
   $db->commit();if($action==='delete')blogCleanupUploads($old);blogEditorRedirect($action==='delete'?'Post and its comments deleted.':($action==='publish'?'Post published. Future-dated posts appear on their publication date.':'Post unpublished.'));
  }catch(Throwable $exception){if($db->inTransaction())$db->rollBack();$errors[]='Could not update this post. Please try again.';}}
 }elseif($action==='save'){
  $editing=true;$edit=$id;$data=$defaults;
  foreach($defaults as $key=>$value)if(is_string($value))$data[$key]=is_string($_POST[$key]??null)?trim($_POST[$key]):$value;
  $data['seo_title']=$old['seo_title']??'';$data['seo_description']=$old['seo_description']??'';$data['is_sample']=$old['is_sample']??false;
  $data['image']=$old['image']??'';$data['gallery']=$old['gallery']??[];$data['youtube_id']='';$data['featured']=($_POST['featured']??'')==='1'?'1':'0';
  if(($_POST['remove_cover']??'')==='1')$data['image']='';
  $removed=is_array($_POST['remove_gallery']??null)?array_filter($_POST['remove_gallery'],'is_string'):[];$data['gallery']=array_values(array_diff($data['gallery'],$removed));
  foreach(['title'=>180,'slug'=>180,'excerpt'=>500,'content'=>100000,'category'=>100,'tags'=>500,'author'=>100,'youtube'=>500,'alt'=>200] as $key=>$max)if(mb_strlen($data[$key])>$max)$errors[]=ucfirst($key).' is too long.';
  if($data['title']===''||$data['author']==='')$errors[]='Title and author are required.';
  if(!in_array($data['type'],['article','image','video','short'],true)||!in_array($data['status'],['draft','published'],true))$errors[]='Choose a valid post type and status.';
  if($data['type']==='article'&&$data['content']==='')$errors[]='Article content is required.';
  if(in_array($data['type'],['video','short'],true)){$data['youtube_id']=blogYoutubeId($data['youtube'])??'';if($data['youtube_id']==='')$errors[]='Enter a valid YouTube video or Shorts link.';}else $data['youtube']='';
  $date=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$data['published_at']);if(!$date||$date->format('Y-m-d\TH:i')!==$data['published_at'])$errors[]='Choose a valid publication date.';
  $slug=strtolower($data['slug']?:$data['title']);$slug=trim(preg_replace('/[^a-z0-9]+/','-',$slug),'-');if($slug==='')$slug='post-'.bin2hex(random_bytes(5));$data['slug']=substr($slug,0,180);
  $uploads=[];$cover=$_FILES['image']??null;
  if(is_array($cover)&&is_scalar($cover['error']??null)&&(int)$cover['error']!==UPLOAD_ERR_NO_FILE)$uploads[]=['kind'=>'image','file'=>$cover];
  $gallery=$_FILES['gallery']??null;
  if(is_array($gallery)&&is_array($gallery['error']??null))foreach($gallery['error'] as $index=>$error)if(is_scalar($error)&&(int)$error!==UPLOAD_ERR_NO_FILE)$uploads[]=['kind'=>'gallery','file'=>['error'=>$error,'tmp_name'=>$gallery['tmp_name'][$index]??'','size'=>$gallery['size'][$index]??0]];
  if(count($data['gallery'])+count(array_filter($uploads,static fn($upload)=>$upload['kind']==='gallery'))>12)$errors[]='Keep up to 12 gallery images. Remove an existing image before adding more.';
  foreach($uploads as &$upload){$file=$upload['file'];$upload['extension']='';
   if((int)$file['error']!==UPLOAD_ERR_OK||!is_string($file['tmp_name'])||!is_uploaded_file($file['tmp_name'])){$errors[]='An image upload failed. Choose images up to 5 MB each.';continue;}
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$upload['extension']=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';$size=@getimagesize($file['tmp_name']);
   if(!$upload['extension']||!$size||(int)$file['size']>5*1024*1024||$size[0]*$size[1]>40000000)$errors[]='Choose JPEG, PNG or WebP images up to 5 MB and 40 megapixels each.';
  }unset($upload);
  $hasCover=$data['image']!==''||count(array_filter($uploads,static fn($upload)=>$upload['kind']==='image'))>0;
  if(in_array($data['type'],['article','image'],true)&&!$hasCover)$errors[]='Upload a cover image for an article or photo story.';
  $created=[];
  if(!$errors){try{
   $directory=dirname(__DIR__).'/assets/uploads';if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))throw new RuntimeException('Upload directory is unavailable.');
   foreach($uploads as $upload){$name='blog-'.bin2hex(random_bytes(16)).'.'.$upload['extension'];$url='./assets/uploads/'.$name;if(!move_uploaded_file($upload['file']['tmp_name'],$directory.'/'.$name))throw new RuntimeException('Could not store an image.');$created[]=$url;if($upload['kind']==='image')$data['image']=$url;else $data['gallery'][]=$url;}
   $db->beginTransaction();$payload=json_encode($data,JSON_THROW_ON_ERROR);
   if($id){$q=$db->prepare('UPDATE blog_posts SET slug=?,payload=? WHERE id=?');$q->execute([$data['slug'],$payload,$id]);}else{$q=$db->prepare('INSERT INTO blog_posts (slug,payload) VALUES (?,?)');$q->execute([$data['slug'],$payload]);}
   $db->commit();if($old)blogCleanupUploads($old,$data);blogEditorRedirect($id?'Post updated.':'Post created.');
  }catch(Throwable $exception){if($db->inTransaction())$db->rollBack();$errors[]=($exception instanceof PDOException&&($exception->errorInfo[1]??0)===1062)?'This slug already exists. Choose a different slug.':'Could not save the post. Please try again.';}}
  if($created){blogCleanupUploads($created);$data['image']=$old['image']??'';$data['gallery']=array_values(array_diff($data['gallery'],$created));}
 }else $errors[]='Invalid action.';
}
$query=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,150):'';$filter=is_string($_GET['status']??null)?$_GET['status']:'';$posts=[];
foreach($db->query('SELECT id,slug,payload FROM blog_posts ORDER BY id DESC') as $row){$post=blogRecord($row);if(($query===''||mb_stripos($post['title'].' '.$post['category'].' '.$post['author'],$query)!==false)&&($filter===''||$post['status']===$filter))$posts[]=$post;}
$layout=($_GET['layout']??'cards')==='list'?'list':'cards';$totalPosts=count($posts);$perPage=6;$totalPages=max(1,(int)ceil($totalPosts/$perPage));$page=max(1,min($totalPages,(int)($_GET['page']??1)));$posts=array_slice($posts,($page-1)*$perPage,$perPage);
function blogListUrl(array $changes=[]): string {global $query,$filter,$layout,$page;return './blog?'.http_build_query(array_merge(['q'=>$query,'status'=>$filter,'layout'=>$layout,'page'=>$page],$changes));}
function blogAdminImage(string $url): string {return str_starts_with($url,'./')?'../'.substr($url,2):$url;}
$notice=$_SESSION['blog_notice']??'';unset($_SESSION['blog_notice']);$pendingComments=(int)$db->query("SELECT COUNT(*) FROM blog_comments WHERE status='pending'")->fetchColumn();$properties=listingData();$view='blog';$title=$editing?($edit?'Edit blog post':'Create blog post'):'Blog';require __DIR__.'/header.php';
?>
