<section class="panel form-section"><h2>Post details</h2><div class="form-grid"><?php foreach(['title'=>'Title','slug'=>'Slug (generated if empty)','author'=>'Author','category'=>'Category','tags'=>'Tags (comma separated)','excerpt'=>'Short description'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= $key ?>" value="<?= e($data[$key]) ?>" maxlength="<?= in_array($key,['tags','excerpt'],true)?500:($key==='author'||$key==='category'?100:180) ?>" <?= in_array($key,['title','author'],true)?'required':'' ?>></label><?php endforeach; ?><label>Post type<select name="type" id="blog-type"><?php foreach(['article'=>'Article','image'=>'Photo story','video'=>'YouTube Video','short'=>'YouTube Short'] as $value=>$label): ?><option value="<?= $value ?>" <?= $data['type']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach(['draft'=>'Draft','published'=>'Published'] as $value=>$label): ?><option value="<?= $value ?>" <?= $data['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Publication date<input type="datetime-local" name="published_at" value="<?= e($data['published_at']) ?>" required></label></div><label>Content / description<textarea name="content" id="blog-content" rows="12" maxlength="100000" placeholder="Write your post. Separate paragraphs with a blank line."><?= e($data['content']) ?></textarea></label><p>Publication dates use Pakistan time (Asia/Karachi). Future-dated published posts stay hidden until their scheduled date.</p><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?= $data['featured']==='1'?'checked':'' ?>> Featured post</label></section>
<section class="panel form-section"><h2>Cover &amp; video</h2><div id="blog-youtube-fields"><label>YouTube URL<input type="url" name="youtube" id="blog-youtube" maxlength="500" value="<?= e($data['youtube']) ?>" placeholder="https://www.youtube.com/watch?v=... or /shorts/..."></label><p>Choose Video for landscape or Short for a vertical preview. Video playback stays on your website.</p><iframe id="blog-video-preview" title="YouTube preview" src="about:blank" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen hidden></iframe><p id="blog-video-message" role="status"></p></div><label>Cover image<input type="file" name="image" id="blog-image" accept="image/jpeg,image/png,image/webp"></label><p>Required for articles and photo stories. Optional for YouTube posts, which can use the video thumbnail. JPEG, PNG or WebP, up to 5 MB.</p><img id="blog-image-preview" src="<?= e(blogAdminImage($data['image'])) ?>" alt="Cover preview" <?= !$data['image']?'hidden':'' ?> data-original="<?= e(blogAdminImage($data['image'])) ?>"><?php if($data['image']): ?><label class="checkbox-label"><input type="checkbox" name="remove_cover" value="1"> Remove current cover</label><?php endif; ?><label>Cover image description<input name="alt" maxlength="200" value="<?= e($data['alt']) ?>"></label><p>Replacing a cover removes the previous uploaded file after saving, unless it is still used elsewhere.</p></section>
